-- Fakt kartochkalari orqa tomonining ruscha matni — 58-partiya:
-- Abror Hidoyatov, Abu Mansur Moturidiy.

UPDATE fact_cards SET detail_ru = 'В пояснении на портале Ziyouz.com отмечено, что Аброр Хидоятов родился в 1900 году, умер в 1958-м и был известным театральным актёром. В учебнике «История театра» точных сведений о месте его рождения не даётся. Источник: библиотека Ziyouz.com.' WHERE id = 2100;
UPDATE fact_cards SET detail_ru = 'В 1918 году он вышел на сцену в числе одарённой молодёжи в труппе «Турон», заново созданной Маннаном Уйгуром. Этот коллектив в 1921 году получил имя «Узбекский государственный образцовый театр», а с 1929 года стал называться именем Хамзы. Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2101;
UPDATE fact_cards SET detail_ru = 'В спектаклях, поставленных Маннаном Уйгуром, он исполнил в 1920 году роль Неъмата в «Халиме», в 1923-м — Фархада в «Фархаде и Ширин», а в 1924-м — главную роль в «Лейли и Меджнун». Его партнёршей на сцене чаще всего была актриса Масума Кариева. Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2102;
UPDATE fact_cards SET detail_ru = 'В учебнике «История театра» написано, что иностранцы изумлялись высокому уровню исполнения таких сочинений, как «Гамлет» и «Отелло», узбекскими актёрами. А академик Камиль Яшин в статье о спектакле «Муканна» отметил: «Великий деятель узбекского театра Аброр Хидоятов вот уже несколько лет играет роль Отелло с несравненным мастерством». Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2103;
UPDATE fact_cards SET detail_ru = 'Сара Эшонтураева в своих воспоминаниях говорит, что роль Гофира первым сыграл Аброр Хидоятов. Спектакль шёл с 1939 по 1982 год 867 раз, а об этой роли актёра писал Александр Дейч в книге «Аброр Хидоятов», изданной в 1985 году. Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2104;
UPDATE fact_cards SET detail_ru = '«Муканну» в 1944 году поставили М. Уйгур и С. Михоэлс, а премьера драмы Уйгуна и Иззата Султана «Алишер Навои» прошла 1 апреля 1945 года. В обоих спектаклях его партнёршей была Сара Эшонтураева (роли Гулоин и Гули), а истолкование Навои у Хидоятова было оценено как «романтико-психологическое решение». Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2105;
UPDATE fact_cards SET detail_ru = 'В воспоминаниях Зикира Мухаммаджанова написано, что его наставник дал ему перепечатанный на машинке список роли Тимура Малика и каждый день в десять часов работал с ним в театре. Слова наставника — «если слово не идёт от сердца, зрителя ты не убедишь» — стали ему уроком на всю жизнь. Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2106;
UPDATE fact_cards SET detail_ru = 'Аброр Хидоятов умер в 1958 году. Память о нём была увековечена: одному из драматических театров Ташкента (бывшему театру «Ёш гвардия») было присвоено имя Аброра Хидоятова. Источник: библиотека Ziyouz.com, учебник «История театра».' WHERE id = 2107;

UPDATE fact_cards SET detail_ru = 'Учёный родился в 870 году. Полное его имя — Абу Мансур Мухаммад ибн Махмуд аль-Ханафи аль-Мотуриди ас-Самарканди, а нисба «аль-Мотуриди» связана с названием селения Мотурид, где он жил. Источник: Ziyouz.com.' WHERE id = 1946;
UPDATE fact_cards SET detail_ru = '«Китаб ат-таухид» — одно из известных сочинений Мотуриди; в статье Ziyouz.com оно приводится в перечне его сочинений. Источник: Ziyouz.com.' WHERE id = 1947;
UPDATE fact_cards SET detail_ru = 'В статье Ziyouz.com перечислены сочинения учёного: «Китаб аль-усул», «Китаб таухид», «Лучшее в основах шариата», «Книга о диалектике» и «Пандноме». Источник: Ziyouz.com.' WHERE id = 1948;
UPDATE fact_cards SET detail_ru = 'По статье Ziyouz.com, после того как Самарканд был занят Исмаилом Самани, учёный оставил дворец правителя Насра и жил в селении Мотурид. Приглашение Исмаила Самани ко двору он отклонил. Источник: Ziyouz.com.' WHERE id = 1949;
UPDATE fact_cards SET detail_ru = 'Учёный был имам-хатибом в большой Соборной мечети Самарканда и работал в собственном саду. Он воспитал очень много учеников. Источник: Ziyouz.com.' WHERE id = 1950;
UPDATE fact_cards SET detail_ru = 'По статье Ziyouz.com, учёный умер в 946 году (335 год хиджры). Его могила находится на самаркандском кладбище Чокардиза. Источник: Ziyouz.com.' WHERE id = 1951;
